import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        matrix.append(row)

    dp = [set() for _ in range(n)]
    parent = [[None] * (1024) for _ in range(n)]

    dp[0] = {matrix[0][j] for j in range(m)}
    for j in range(m):
        val = matrix[0][j]
        parent[0][val] = j

    for i in range(1, n):
        current_row = matrix[i]
        prev_set = dp[i-1]
        curr_set = set()

        for val in prev_set:
            for j in range(m):
                new_val = val ^ current_row[j]
                if new_val not in dp[i]:
                    dp[i].add(new_val)
                    parent[i][new_val] = (j, val)
        if not dp[i]:
            break

    if not dp[n-1] or 0 not in dp[n-1]:
        if not dp[n-1]:
            print("NIE")
            return
        found = False
        for val in dp[n-1]:
            if val != 0:
                found = True
                target = val
                break
        if not found:
            print("NIE")
            return
    else:
        found = False
        for val in dp[n-1]: 
            if val != 0:
                found = True
                target_val = val
                break
        if not found:
            print("NE")
            return
        target = target_val

    path = []
    curr = target
    for i in range(n-1, -1, -1):
        if i == n-1:
            if curr not in dp[i]:
                break
            idx = parent[i][curr]
            path.append(idx + 1)
            prev_val = curr ^ matrix[i][idx]
        else:
            if curr not in dp[i]:
                break
            p = parent[i][curr]
            if isinstance(p, tuple):
                idx, prev_val = p
                path.append(idx + 1)
                curr = prev_val
            else:
                idx = p
                path.append(idx + 1)
                curr = curr ^ matrix[i][idx]

    path.reverse()
    print("TAK")
    print(*(path))

if __name__ == "__main__":
    solve()
